#!/bin/bash
# PROTOCOL.md AMENDMENT 1, A5 -- 20 FULLY MATCHED NULL RUNS for gate B1.
#
# Each run scrambles the world (20-day blocks within the year, direction
# flipped with p=0.5), draws 200,000 complete algorithms, runs the local
# search from the top 200 at the same cap, builds the full 28-pair sleeve
# bank, then rebuilds EVERY book of item 3 and takes item 2's statistics.
# A null that does not repeat the SELECTION measures nothing about selection.
#
# DO NOT EDIT THIS FILE, nnfxbooks.py, nnfxnullrun.py, nnfxsleeves.py OR
# nnfxfit.py WHILE THIS IS RUNNING. Bash reads a script incrementally as it
# executes, and a Python worker imports its modules once at start -- an edit
# reaches the workers that have not started yet and not the ones that have,
# which is the worst of both.
#
# RESUMABLE BY RUN: a run whose books_NNN.csv and fit_NNN.csv are both on disk
# is skipped, so a killed batch costs the runs in flight and no more.
# STOP WITH: bash code/chain/stop_chain.sh $(cat results/chainlogs/booknull.pgid)
set -u
cd /Users/jackcuster/fx-data
export FX_COST_TABLE=results/cost_table_h22.csv
LOG=results/chainlogs/booknull.log
ts(){ date "+[%H:%M:%S]"; }
echo "$(ts) START booknull -- 20 matched runs, 7 workers, measured ~57 min each" >> $LOG
seq 0 19 | xargs -P 7 -I{} sh -c \
  'FX_COST_TABLE=results/cost_table_h22.csv python3 code/nnfxnullrun.py --run {} > results/chainlogs/booknull_{}.log 2>&1 || echo "$(date +%H:%M:%S) FAIL run {}" >> results/chainlogs/booknull.log'
NDONE=$(ls results/nnfx/books/null/books_*.csv 2>/dev/null | wc -l | tr -d ' ')
echo "$(ts) OK booknull -- $NDONE of 20 runs on disk" >> $LOG
echo "$(ts) DONE booknull" >> $LOG
